import{d as g,C as n,o as d,c as p,E as i,a3 as a}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"既济卦","description":"第六十三卦·水火既济——水在火上，六爻皆正；渡河已成，平衡靠张力撑着，患在感知消失的那一刻。","frontmatter":{"title":"既济卦","description":"第六十三卦·水火既济——水在火上，六爻皆正；渡河已成，平衡靠张力撑着，患在感知消失的那一刻。","category":"hexagram","aliases":["既济","水火既济"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-63.md","filePath":"yijing/hexagrams/hexagram-63.md","lastUpdated":1787730063000}'),h={name:"yijing/hexagrams/hexagram-63.md"},x=g({...h,setup(u){const r=[{id:"jiji",term:"既济",pinyin:"jì jì",meaning:"渡河已经完成。济为渡，既为已经。",context:"六十四卦中唯一的六爻皆正，也是最危险的一卦。"},{id:"yeqilun",term:"曳其轮",pinyin:"yè qí lún",meaning:"拖住车轮，主动刹车。",context:"初九刚渡之始，刹住冲出去的惯性。"},{id:"ruqiwei",term:"濡其尾",pinyin:"rú qí wěi",meaning:"打湿尾巴——渡河时入水过深，付出的代价。",context:"尾湿是代价，不是失败。"},{id:"fu",term:"茀",pinyin:"fú",meaning:"车厢的遮蔽、妇人出行的仪仗依凭。"},{id:"wuzhu",term:"勿逐",pinyin:"wù zhú",meaning:"不要去追、不要去抢。",context:"越追越乱；稳坐等待，失去的自会归位。"},{id:"qiride",term:"七日得",pinyin:"qī rì dé",meaning:"七日后自然失而复得。",context:"七是天道循环的小周期；以中道为锚，等时间归位。"},{id:"gaozong",term:"高宗",pinyin:"gāo zōng",meaning:"商王武丁，中兴之主。"},{id:"faguifang",term:"伐鬼方",pinyin:"fá guǐ fāng",meaning:"征伐西北强族鬼方。",context:"硬仗打三年，胜利本身就疲惫。"},{id:"bei",term:"惫",pinyin:"bèi",meaning:"疲惫。「三年克之，惫也」——战胜已是筋疲力尽。"},{id:"xuyouyiru",term:"繻有衣袽",pinyin:"xū yǒu yī rú",meaning:"华服与破絮俱备——盛时不忘备患。",context:"既穿得好，也随时备着堵漏的东西。"},{id:"yiru",term:"衣袽",pinyin:"yī rú",meaning:"破絮、旧衣——船上的渗漏与堵漏之物，喻备患。"},{id:"zhongrijie",term:"终日戒",pinyin:"zhōng rì jiè",meaning:"整天警戒。",context:"不是焦虑，是清醒知道自己站在水上。"},{id:"yueji",term:"禴祭",pinyin:"yuè jì",meaning:"夏祭、薄祭——祭品菲薄而心诚。",context:"神明感应的不是祭品的重量，是心意的真实。"},{id:"rushou",term:"濡其首",pinyin:"rú qí shǒu",meaning:"水淹到头。",context:"厉是最后的警醒，不是凶。"},{id:"sihuan yufang",term:"思患豫防",pinyin:"sī huàn yù fáng",meaning:"思考患难、预先设防。",context:"患在感知消失的那一刻。"}],e=[{position:"初九",type:"yang",text:"曳其轮，濡其尾，无咎。",xiang:"曳其轮，义无咎也。",textModern:"拖住车轮、尾巴沾湿入水——刚渡之始先刹住冲动，付出一点代价，没有灾咎。",xiangModern:"拖住车轮主动刹车，在义理上没有灾咎。"},{position:"六二",type:"yin",text:"妇丧其茀，勿逐，七日得。",xiang:"七日得，以中道也。",textModern:"妇人丢失了依凭的车饰，不要去追，七天后自然会失而复得。",xiangModern:"七日后重得，是因为守持中道——六二居下卦之中，正位的人不怕失去。"},{position:"九三",type:"yang",text:"高宗伐鬼方，三年克之，小人勿用。",xiang:"三年克之，惫也。",textModern:"高宗征伐鬼方，苦战三年才攻克；不要任用小人、不要走捷径。",xiangModern:"三年才攻克，是因为硬仗打到疲惫——胜利本身已筋疲力尽。"},{position:"六四",type:"yin",text:"繻有衣袽，终日戒。",xiang:"终日戒，有所疑也。",textModern:"华服与破絮俱备，整天保持警戒——清醒知道自己仍站在水上。",xiangModern:"终日戒备，是因为心知身处险中——有所疑，正是没有麻痹。"},{position:"九五",type:"yang",text:"东邻杀牛，不如西邻之禴祭，实受其福。",xiang:"东邻杀牛，不如西邻之时也。实受其福，吉大来也。",textModern:"东邻杀牛盛祭，不如西邻菲薄而诚的禴祭——后者实实在在地承受福泽。",xiangModern:"杀牛不如禴祭，是时与诚的差别；诚心实受其福，大吉才真正到来。"},{position:"上六",type:"yin",text:"濡其首，厉。",xiang:"濡其首厉，何可久也。",textModern:"水淹到头，危厉——渡河没有终点，只有下一条河。",xiangModern:"水淹到头而危厉，这样的状态怎么能长久呢。"}];return(m,t)=>{const o=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),s=n("DaoKeywordCards");return d(),p("div",null,[i(o,{name:"既济",fullName:"水火既济",upper:"☵",lower:"☲",guaCi:"既济，亨小，利贞。初吉终乱。",pinyin:["jì","jì"],element:"水",direction:"北",insight:"水在火上，六爻皆正；渡河已成，却处处是水的边际——平衡靠张力撑着，患在感知消失的那一刻。",guaSlug:"63shuihuojiji",lines:e}),t[0]||(t[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>水在火上，既济。君子以思患而豫防之。</p><p>水在火上、水火相交各得其所，是渡河已成之象；君子由此领悟，要在安定中思考患难、预先设防。</p><p>「思患而豫防之」——<strong>思患</strong>，是把患想在前面；<strong>豫防</strong>，是预先设防。既济最危险的地方，恰恰是它看起来最安全。已经渡完河的人，最容易忘了水。</p><p>分形结构：</p><ul><li>思患（想）→ 微观：把隐患写进今天的日程</li><li>豫防（防）→ 宏观：在系统里预设冗余与退路</li></ul><p>既济的平衡不是静止的，是张力撑出来的——火在烧、水在沸，两者互相制衡才成「济」。张力消失的那一刻，才是真正的患。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>既济亨，小者亨也。利贞，刚柔正而位当也。初吉，柔得中也。终止则乱，其道穷也。</p><p>逐句释义：</p><ul><li><strong>既济亨，小者亨也</strong> —— 既济之所以亨通，是「小事」的亨通。济成之后，能亨通的多是细碎日常，没有轰轰烈烈。</li><li><strong>利贞，刚柔正而位当也</strong> —— 利于守正，因为六爻阴阳各归其位、刚柔各得其正。既济是唯一六爻皆正的卦——但它恰恰因此危险。</li><li><strong>初吉，柔得中也</strong> —— 起初吉祥，是因为六二柔爻居中得正，渡河之始还保有谦柔的节制。</li><li><strong>终止则乱，其道穷也</strong> —— 到了终点就停止，则乱；因为既济之后道已穷尽，没有下一程。这正是「初吉终乱」的出处。</li></ul><blockquote><p><strong>张力哲学</strong>：六爻皆正不是保险箱，是悬崖边搭好的平衡木。正，恰恰需要每一刻的维系。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),i(l,{element:"水",guaSlug:"63shuihuojiji",glossary:r,items:e}),t[1]||(t[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初九-·-曳其轮-濡其尾-无咎" tabindex="-1">初九 · 曳其轮，濡其尾，无咎 <a class="header-anchor" href="#初九-·-曳其轮-濡其尾-无咎" aria-label="Permalink to &quot;初九 · 曳其轮，濡其尾，无咎&quot;">​</a></h3><ul><li><strong>曳其轮</strong> → 拖住车轮，主动刹车</li><li><strong>濡其尾</strong> → 尾巴沾湿——渡河时入水太深，付出代价</li><li><strong>无咎</strong> → 没有灾咎</li></ul><p>初九是渡河的第一步。刚渡之始，冲劲最强——曳其轮，是刚靠岸就刹住冲出去的惯性；濡其尾，是承认这一步已经付出的代价。尾湿不是失败，是代价。</p><p><strong>刹车智慧</strong>：最会渡河的人，不是划得最快的人，是知道什么时候该拖住轮子的人。既济的开局，先立规矩，再谈赶路。</p><blockquote><p>核心洞见：尾湿是代价非失败。承认代价的人，才不会被代价追着跑。</p></blockquote><h3 id="六二-·-妇丧其茀-勿逐-七日得" tabindex="-1">六二 · 妇丧其茀，勿逐，七日得 <a class="header-anchor" href="#六二-·-妇丧其茀-勿逐-七日得" aria-label="Permalink to &quot;六二 · 妇丧其茀，勿逐，七日得&quot;">​</a></h3><ul><li><strong>茀</strong> → 车厢的遮蔽、妇人出行的仪仗依凭</li><li><strong>丧其茀</strong> → 失去了依凭</li><li><strong>勿逐</strong> → 不要去追</li><li><strong>七日得</strong> → 七天后自然失而复得</li></ul><p>六二阴爻居下卦之中，正位。正位的人不怕失去依凭——茀丢了，追是追不回来的，越追越乱。勿逐，是稳坐等待。</p><p><strong>正位重获</strong>：失去的不是能力，是外部的装饰性依凭。位置正的人，失去的东西会在时间里自己回来。</p><blockquote><p>核心洞见：勿逐不是躺平，是以中道为锚，等失去的东西自己归位。</p></blockquote><h3 id="九三-·-高宗伐鬼方-三年克之-小人勿用" tabindex="-1">九三 · 高宗伐鬼方，三年克之，小人勿用 <a class="header-anchor" href="#九三-·-高宗伐鬼方-三年克之-小人勿用" aria-label="Permalink to &quot;九三 · 高宗伐鬼方，三年克之，小人勿用&quot;">​</a></h3><ul><li><strong>高宗</strong> → 商王武丁，中兴之主</li><li><strong>伐鬼方</strong> → 征伐西北强族鬼方</li><li><strong>三年克之</strong> → 苦战三年才攻克</li><li><strong>小人勿用</strong> → 不要任用小人——不要取巧的手段，不要急躁的心</li></ul><p>九三阳爻居刚位，是既济里最「能打」的一爻。但爻辞给出的，不是速胜，是持久战。</p><p><strong>长期主义</strong>：硬仗打三年，克是疲惫地克（三年克之，惫也）。既济之中最硬的仗，恰恰没有捷径。小人勿用——忍住内心那个想抄近路、想夸大战果、想在胜利上多分一杯羹的小我。小人不是别人，是急。</p><blockquote><p>核心洞见：三年克之，惫也——胜利本身就带着疲惫。真赢的人，不急着炫耀赢。</p></blockquote><h3 id="六四-·-繻有衣袽-终日戒" tabindex="-1">六四 · 繻有衣袽，终日戒 <a class="header-anchor" href="#六四-·-繻有衣袽-终日戒" aria-label="Permalink to &quot;六四 · 繻有衣袽，终日戒&quot;">​</a></h3><ul><li><strong>繻</strong> → 华美的彩缯</li><li><strong>衣袽</strong> → 破絮、旧衣——船上的渗漏与堵漏之物</li><li><strong>终日戒</strong> → 整天保持警戒</li></ul><p>六四阴爻居坎体（水上），最接近水的一爻。繻有衣袽——华服与破絮俱备，既穿得好，也随时备着堵漏的东西。终日戒，不是焦虑，是清醒知道自己正站在水上。</p><p><strong>身处险中自知</strong>：已经过了河的人，最容易忘了脚下是水。终日戒，是把「我在水上」写进每一刻的底层状态。</p><blockquote><p>核心洞见：终日戒是底层状态——不是紧张地防着什么，是平静地知道自己在哪里。</p></blockquote><h3 id="九五-·-东邻杀牛-不如西邻之禴祭-实受其福" tabindex="-1">九五 · 东邻杀牛，不如西邻之禴祭，实受其福 <a class="header-anchor" href="#九五-·-东邻杀牛-不如西邻之禴祭-实受其福" aria-label="Permalink to &quot;九五 · 东邻杀牛，不如西邻之禴祭，实受其福&quot;">​</a></h3><ul><li><strong>东邻杀牛</strong> → 东邻杀牛大祭，祭品丰盛</li><li><strong>西邻之禴祭</strong> → 西邻薄祭（夏祭），祭品菲薄</li><li><strong>实受其福</strong> → 实实在在地承受福泽</li></ul><p>九五居君位，是既济的鼎盛之爻。鼎盛之时，人最容易被「大」诱惑——杀牛。但爻辞说：杀牛，不如薄祭。</p><p><strong>诚意重于形式</strong>：神明感应的不是牛的重量，是心意的真实。既济之极，形式最完备，诚意最容易被形式淹没。回到禴祭，回到真实当下。</p><blockquote><p>核心洞见：杀牛是给外人看的，禴祭是给自己心的。真正受福的，是诚，不是丰。</p></blockquote><h3 id="上六-·-濡其首-厉" tabindex="-1">上六 · 濡其首，厉 <a class="header-anchor" href="#上六-·-濡其首-厉" aria-label="Permalink to &quot;上六 · 濡其首，厉&quot;">​</a></h3><ul><li><strong>濡其首</strong> → 水淹到头</li><li><strong>厉</strong> → 危厉、警示</li></ul><p>既济走到上六，水已经淹到头。既济没有终点——渡完这条河，前面就是下一条河（未济）。濡其首，是因为忘了「没有终点」这件事，在成就里睡着了。</p><p><strong>厉是最后的警醒，不是凶</strong>：厉，是最后一声提醒：还可以醒。真正凶的，不是淹到头，是淹到头还觉得自己安全。</p><blockquote><p>核心洞见：没有终点，只有下一条河。既济的完成，恰恰是未济的开始。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',32)),i(s,{title:"字词释义",items:[{term:"既济",pinyin:["jì","jì"],meaning:"渡河已经完成。济为渡，既为已经。六十四卦中唯一的六爻皆正。"},{term:"曳其轮",pinyin:["yè","qí","lún"],meaning:"拖住车轮、主动刹车，遏制前行的惯性。"},{term:"濡其尾",pinyin:["rú","qí","wěi"],meaning:"打湿尾巴——渡河时入水过深，付出的代价。尾湿是代价，不是失败。"},{term:"茀",pinyin:["fú"],meaning:"车厢的遮蔽、妇人出行的仪仗依凭。「妇丧其茀」即失去依凭。"},{term:"勿逐",pinyin:["wù","zhú"],meaning:"不要去追、不要去抢。越追越乱，稳坐等待，失去的自会归位。"},{term:"七日得",pinyin:["qī","rì","dé"],meaning:"七日后自然失而复得。七为天道循环的小周期。"},{term:"高宗伐鬼方",pinyin:["gāo","zōng","fá","guǐ","fāng"],meaning:"商王武丁征伐西北强族鬼方——硬仗持久战的象征。"},{term:"惫",pinyin:["bèi"],meaning:"疲惫。「三年克之，惫也」——胜利本身就带着疲惫。"},{term:"衣袽",pinyin:["yī","rú"],meaning:"破絮、旧衣——船上的渗漏与堵漏之物，喻备患。"},{term:"繻有衣袽",pinyin:["xū","yǒu","yī","rú"],meaning:"华服与破絮俱备——盛时不忘备患。"},{term:"终日戒",pinyin:["zhōng","rì","jiè"],meaning:"整天警戒。不是焦虑，是清醒知道自己站在水上。"},{term:"东邻杀牛",pinyin:["dōng","lín","shā","niú"],meaning:"东邻杀牛大祭——形式完备而心未必诚。"},{term:"禴祭",pinyin:["yuè","jì"],meaning:"夏祭、薄祭——祭品菲薄而心诚。神明感应的不是祭品的重量，是心意的真实。"},{term:"濡其首",pinyin:["rú","qí","shǒu"],meaning:"水淹到头。厉是最后的警醒，不是凶。"},{term:"思患豫防",pinyin:["sī","huàn","yù","fáng"],meaning:"思考患难、预先设防。患不在当下，在感知消失的那一刻。"}]}),t[2]||(t[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>既济讲的是<strong>渡河已经完成之后的平衡</strong>。上坎（水）在下离（火）上，水在火上、水火相交各得其所；六爻阴阳各归其位，是六十四卦中唯一六爻皆正的卦——事物达到最和谐、最完备的状态。</p><p>但卦辞紧跟着泼下冷水：「初吉终乱」。完成不是终点，是最危险的时刻——因为完成之后，警惕最容易松懈。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>既济告诉我们：<strong>平衡不是静止的，是张力撑出来的</strong>。水火相济靠的是两者互相制衡——火太旺则水沸，水太盛则火灭。平衡是需要持续做功的状态，不是可以躺下的地方。</p><p>「思患而豫防之」——患不在过去，不在当下，而在<strong>感知消失的那一刻</strong>。当你觉得一切稳定了、安全了、没问题了，那才是真正的患。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>曳其轮：开局先刹住冲动，立好规矩再赶路</li><li>勿逐：失去依凭时稳坐等待，以中道为锚</li><li>长期主义：硬仗没有捷径，忍住内心的小人</li><li>终日戒：把「我在水上」写进底层状态，靠清醒而非焦虑</li><li>回到禴祭：少一点杀牛（形式、分量），多一点诚（真实当下）</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>既济卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>既济亨小，利贞，初吉终乱</td><td>完成时刻最危险</td><td>初吉终乱</td></tr><tr><td>初九</td><td>曳其轮，濡其尾，无咎</td><td>刚渡之始刹住冲动，尾湿是代价非失败</td><td>刹车智慧</td></tr><tr><td>六二</td><td>妇丧其茀，勿逐，七日得</td><td>失去依凭，稳坐等待</td><td>正位重获</td></tr><tr><td>九三</td><td>高宗伐鬼方，三年克之，小人勿用</td><td>硬仗持久战，忍住内心的小人</td><td>长期主义</td></tr><tr><td>六四</td><td>繻有衣袽，终日戒</td><td>身处险中自知</td><td>终日戒</td></tr><tr><td>九五</td><td>东邻杀牛，不如西邻之禴祭</td><td>诚意重于形式</td><td>禴祭</td></tr><tr><td>上六</td><td>濡其首，厉</td><td>没有终点，只有下一条河</td><td>濡其首</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>张力即平衡</strong>——平衡是撑出来的，不是躺出来的</li><li><strong>渡河不是终点</strong>——完成即未济的开始</li><li><strong>诚意重于形式</strong>——神明感应的是心意，不是重量</li><li><strong>终日戒是底层状态</strong>——清醒知道自己在水上</li><li><strong>没有终点</strong>——既济的完成，是未济的开始</li><li><strong>思患豫防</strong>——患在感知消失的那一刻</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>既济对应我此刻的状态：三个「鬼方」的持久战——羽毛球、易经研习、全栈转型。每一个都是高宗伐鬼方：三年未必够，硬仗没有捷径，只能一天一天地克。</p><ul><li><strong>衣袽</strong>：我备着的堵漏之物——把教训写下来、把复盘留档。华服之下，永远备着破絮。</li><li><strong>禴祭</strong>：回到薄祭，回到真实当下——不靠外部的仪式感证明自己。</li></ul><p>「杀牛」的警示：当我在意文档好不好看、计划完不完整、成果有没有分量时，我就是在杀牛。杀牛是给外人看的，禴祭是给自己心的。回到禴祭——写一句真话，胜过一个漂亮的空壳。</p><p>既济对我不是「完成了」，是「正站在水上」——终日戒，是底层状态。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：未济（第六十四卦）、离（第三十卦）、坎（第二十九卦）</li><li>既济与未济的连结：六十四卦以既济（完成）居六十三，却以未济（未完成）压轴收尾——完成之后永远有未完成。渡完这条河，前面就是下一条河：既济之后是未济。</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',21))])}}});export{y as __pageData,x as default};
